// warnf writes a "graph:"-prefixed warning line to w, painting the prefix in
// the entire CLI palette's warning yellow (entireio/cli
// cmd/entire/cli/palette/palette.go @ bc9a821d) when w is a color-capable
// terminal. It exists for diagnostic paths that write straight to stderr with
// no renderer in scope. On a pipe the output is byte-identical to a plain
// fmt.Fprintf("graph: ...\n"); the message is neutralized either way because
// it can embed repository-derived error text.
func warnf(w io.Writer, format string, args ...any) {
	prefix := "graph:"
	if sem.ShouldUseColor(w) {
		prefix = "\x1b[33m" + prefix + "\x1b[0m" // palette.Warning (yellow)
	}
	fmt.Fprintf(w, "%s %s\n", prefix, termsafe.Line(fmt.Sprintf(format, args...)))
}

